// Live AI summary on /query pages: the summary is generated by a Celery task
// and pushed over Socket.IO into #theme-summary-container when ready.
const setupQuerySummary = () => {
  const container = document.getElementById("theme-summary-container");
  if (!container) return;

  if (container.querySelector(".type-it") && window.TypeIt) {
    new TypeIt(".type-it", { loop: true }).go();
  }

  const roomId = container.dataset.queryTaskId;
  if (roomId && window.io) {
    const socket = io();
    socket.on("connect", () => {
      socket.emit("join_room", { room_id: roomId });
    });
    socket.on("msg", (data) => {
      container.innerHTML = data.msg;
    });
  }
};

document.addEventListener("DOMContentLoaded", setupQuerySummary);
